void clip_6900_1_1(Activation& scope) {
    if (_root["PauseGame"] == false && _root["playpause"] == false) {
        if (scope["started"] == true) {
            scope["_rotation"] += scope["speed"];
            scope["_y"] += scope["fallspeed"];
        }
        //
        scope["ydistance"] = (scope["_y"] + scope["_parent"]["_y"]) - _root["Course"]["Char"]["_y"];
        scope["xdistance"] = (scope["_x"] + scope["_parent"]["_x"]) - _root["Course"]["Char"]["_x"];
        scope["distance"] = Math["sqrt"](Math["pow"](scope["xdistance"], 2) + Math["pow"](scope["ydistance"], 2));
        scope["rot"] = Math["atan2"](scope["ydistance"], scope["xdistance"]);
        scope["xdiff"] = Math["cos"](scope["rot"]) * scope["distance"] - Math["cos"](scope["rot"] + _root["angleToRadians"](scope.self["speed"])) * scope["distance"];
        scope["ydiff"] = Math["sin"](scope["rot"]) * scope["distance"] - Math["sin"](scope["rot"] + _root["angleToRadians"](scope.self["speed"])) * scope["distance"];
        //
        if (scope["hitTest"]((_root["Course"]["Char"]["_x"] * _root["coursescale"] / 100) + _root["Course"]["_x"], ((_root["Course"]["Char"]["_y"] + 3) * _root["coursescale"] / 100) + _root["Course"]["_y"], true) && _root["Course"]["Char"]["air"] == false) {
            _root["Course"]["Char"]["_x"] += scope["xdiff"];
            _root["Course"]["Char"]["_y"] += scope["ydiff"] + scope["fallspeed"];
            //_root.Course.Char.xspeed = _root.groundFriction(_root.Course.Char.xspeed, 0.3, 1.1);
            if (scope["landedon"] == false) {
                _root["Course"]["Char"]["xspeed"] -= scope["xdiff"];
                //
            }
            scope["landedon"] = true;
            _root["Course"]["FrontGFX"]["fall1"]["started"] = true;
            scope["started"] = true;
        } else {
            if (scope["landedon"] == true) {
                _root["Course"]["Char"]["xspeed"] += scope["xdiff"];
                _root["Course"]["Char"]["yspeed"] += scope["ydiff"];
            }
            scope["landedon"] = false;
        }
    }
}

